import math

def tiles_in_circle(r: int) -> int:
    """Lattice points with x^2 + y^2 <= r^2 (no card knows a faster exact form: kept)."""
    count = 0
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x * x + y * y <= r * r:
                count += 1
    return count

